from _shared import request_json, qs
MANIFEST={"apiVersion":1,"id":"open-meteo-uv","name":"UV · Open-Meteo","description":"Show current UV index and clear-sky UV using Open-Meteo without an API key.","version":"1.0","icon":"☀","refreshMin":30,"kind":"status","access":"no-key","freedomNote":"No account or API key. Open-Meteo is open source and can be self-hosted.","settings":[{"key":"latitude","label":"Latitude","type":"number","required":True},{"key":"longitude","label":"Longitude","type":"number","required":True}]}
def fetch(s,c):
 url=qs('https://air-quality-api.open-meteo.com/v1/air-quality',{'latitude':float(s.get('latitude')),'longitude':float(s.get('longitude')),'current':'uv_index,uv_index_clear_sky','timezone':'auto'}); data,_,_=request_json(c,url); cur=data.get('current') or {}; uv=cur.get('uv_index')
 return {'kind':'status','provider':'Open-Meteo','title':'UV Index','value':uv if uv is not None else '—','details':[{'label':'Clear sky','value':cur.get('uv_index_clear_sky')},{'label':'Updated','value':cur.get('time')}]}
